-- National Organized Showdown Front-Base roster (Gen 1–9)
-- Sprites: Front Base only. Backs never in play. Legendary auto-spawn stays off.

alter table public.species drop constraint if exists species_dex_check;
alter table public.species add constraint species_dex_check check (dex between 1 and 1025);

alter table public.catches drop constraint if exists catches_dex_check;
alter table public.catches add constraint catches_dex_check check (dex between 1 and 1025);

alter table public.species_seen drop constraint if exists species_seen_dex_check;
alter table public.species_seen add constraint species_seen_dex_check check (dex between 1 and 1025);

alter table public.profiles drop constraint if exists profiles_favorite_dex_check;
alter table public.profiles add constraint profiles_favorite_dex_check check (favorite_dex is null or favorite_dex between 1 and 1025);

alter table public.trade_listings drop constraint if exists trade_listings_want_dex_check;
alter table public.trade_listings add constraint trade_listings_want_dex_check check (want_dex is null or want_dex between 1 and 1025);

alter table private.special_events drop constraint if exists special_events_dex_check;
alter table private.special_events add constraint special_events_dex_check check (dex between 1 and 1025);

